// Inlines the matching chunks into the HTML generated by html-webpack-plugin,
// so dist/index.html is a single self-contained file (Figma loads the plugin
// UI from one HTML string and cannot fetch a separate ui.js).
//
// Replaces InlineChunkHtmlPlugin from react-dev-utils, which is abandoned.
// It behaves the same way: a <script src> tag whose file name matches one of
// `tests` becomes an inline <script> with the asset's source, and the chunk
// file itself is still emitted.

const PLUGIN_NAME = 'InlineChunkHtmlPlugin';

class InlineChunkHtmlPlugin {
  /**
   * @param {typeof import('html-webpack-plugin')} htmlWebpackPlugin
   * @param {RegExp[]} tests file names of the chunks to inline
   */
  constructor(htmlWebpackPlugin, tests) {
    this.htmlWebpackPlugin = htmlWebpackPlugin;
    this.tests = tests;
  }

  getInlinedTag(publicPath, compilation, tag) {
    if (tag.tagName !== 'script' || !(tag.attributes && tag.attributes.src)) {
      return tag;
    }

    const scriptName = publicPath
      ? tag.attributes.src.replace(publicPath, '')
      : tag.attributes.src;

    if (!this.tests.some((test) => scriptName.match(test))) {
      return tag;
    }

    const asset = compilation.getAsset(scriptName);
    if (!asset) {
      return tag;
    }

    return {
      tagName: 'script',
      voidTag: false,
      attributes: {},
      meta: { plugin: PLUGIN_NAME },
      innerHTML: asset.source.source(),
    };
  }

  /** @param {import('webpack').Compiler} compiler */
  apply(compiler) {
    let publicPath = compiler.options.output.publicPath || '';
    if (publicPath && !publicPath.endsWith('/')) {
      publicPath += '/';
    }

    compiler.hooks.compilation.tap(PLUGIN_NAME, (compilation) => {
      const tagFunction = (tag) =>
        this.getInlinedTag(publicPath, compilation, tag);

      const hooks = this.htmlWebpackPlugin.getHooks(compilation);
      hooks.alterAssetTagGroups.tap(PLUGIN_NAME, (assets) => {
        assets.headTags = assets.headTags.map(tagFunction);
        assets.bodyTags = assets.bodyTags.map(tagFunction);
      });
    });
  }
}

module.exports = InlineChunkHtmlPlugin;
